//! The SECG named curves, read from the repository's standards database.
//!
//! `docs/curves/standards/parameters.json` is the one place the repository
//! keeps published curve constants.  This module embeds it and returns the
//! `secp…` and `sect…` entries as typed values, so the `ic` tool and the
//! small-x yield measurements ([`super::prime_small_x`],
//! [`super::binary_small_x`]) take their constants from it and not from a
//! second hand-typed copy.
//!
//! Group order in this file always means the order `n` of the subgroup
//! generated by the published base point `G`; the whole group has `h·n`
//! points with `h` the cofactor.  Every SECG entry has `n` prime.

use std::sync::OnceLock;

use num_bigint::BigUint;
use num_traits::Num;
use serde_json::Value;

const PARAMETERS_JSON: &str = include_str!("../../docs/curves/standards/parameters.json");

/// The field of a SECG curve.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SecgField {
    /// `F_p`, with the modulus.
    Prime { p: BigUint },
    /// `F_2[z]/(z^degree + Σ z^t)`, with the exponents `t < degree`
    /// ascending.
    Binary { degree: u32, low_terms: Vec<u32> },
}

/// One SECG curve.  Prime fields: `y² = x³ + a·x + b`.  Binary fields:
/// `y² + x·y = x³ + a·x² + b`, field elements as bit-vectors of
/// polynomial-basis coefficients.
#[derive(Clone, Debug)]
pub struct SecgCurve {
    pub name: String,
    pub oid: String,
    pub field: SecgField,
    pub a: BigUint,
    pub b: BigUint,
    pub gx: BigUint,
    pub gy: BigUint,
    /// Order of the subgroup generated by `G`; prime.
    pub order: BigUint,
    pub cofactor: u64,
}

impl SecgCurve {
    /// Bits of the field: `⌈log₂ p⌉` or the extension degree.
    pub fn field_bits(&self) -> u32 {
        match &self.field {
            SecgField::Prime { p } => p.bits() as u32,
            SecgField::Binary { degree, .. } => *degree,
        }
    }

    pub fn is_binary(&self) -> bool {
        matches!(self.field, SecgField::Binary { .. })
    }
}

fn hex(v: &Value, what: &str) -> Result<BigUint, String> {
    let s = v
        .as_str()
        .ok_or_else(|| format!("{what} is not a string"))?;
    let digits = s.strip_prefix("0x").unwrap_or(s);
    BigUint::from_str_radix(digits, 16).map_err(|e| format!("{what}: {e}"))
}

fn entry(v: &Value) -> Result<SecgCurve, String> {
    let name = v["name"]
        .as_str()
        .ok_or("entry without a name")?
        .to_string();
    let ctx = |what: &str| format!("{name}: {what}");
    let field = &v["field"];
    let field = match field["type"].as_str() {
        Some("Prime") => SecgField::Prime {
            p: hex(&field["p"], &ctx("p"))?,
        },
        Some("Binary") => {
            let degree = field["degree"].as_u64().ok_or_else(|| ctx("degree"))? as u32;
            let mut low_terms: Vec<u32> = field["poly"]
                .as_array()
                .ok_or_else(|| ctx("poly"))?
                .iter()
                .filter_map(|t| t["power"].as_u64())
                .map(|t| t as u32)
                .filter(|&t| t < degree)
                .collect();
            low_terms.sort_unstable();
            low_terms.dedup();
            SecgField::Binary { degree, low_terms }
        }
        other => return Err(ctx(&format!("unsupported field type {other:?}"))),
    };
    let cofactor = hex(&v["cofactor"], &ctx("cofactor"))?;
    Ok(SecgCurve {
        oid: v["oid"].as_str().unwrap_or_default().to_string(),
        a: hex(&v["params"]["a"]["raw"], &ctx("a"))?,
        b: hex(&v["params"]["b"]["raw"], &ctx("b"))?,
        gx: hex(&v["generator"]["x"]["raw"], &ctx("Gx"))?,
        gy: hex(&v["generator"]["y"]["raw"], &ctx("Gy"))?,
        order: hex(&v["order"], &ctx("order"))?,
        cofactor: u64::try_from(cofactor).map_err(|_| ctx("cofactor is not a small integer"))?,
        field,
        name,
    })
}

fn all() -> &'static Vec<SecgCurve> {
    static CURVES: OnceLock<Vec<SecgCurve>> = OnceLock::new();
    CURVES.get_or_init(|| {
        let doc: Value = serde_json::from_str(PARAMETERS_JSON)
            .expect("docs/curves/standards/parameters.json is valid JSON");
        doc["curves"]
            .as_array()
            .expect("a curves array")
            .iter()
            .filter(|c| c["category"].as_str() == Some("secg"))
            .map(|c| entry(c).unwrap_or_else(|e| panic!("standards database: {e}")))
            .collect()
    })
}

/// Names of every SECG curve in the database.
pub fn secg_names() -> Vec<&'static str> {
    all().iter().map(|c| c.name.as_str()).collect()
}

/// The SECG curve called `name` (`secp160r1`, `sect163r2`, …), ignoring case.
pub fn secg(name: &str) -> Option<&'static SecgCurve> {
    let want = name.trim().to_ascii_lowercase();
    all().iter().find(|c| c.name.to_ascii_lowercase() == want)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::binary_ecc::{BinaryCurve, BinaryPoint};

    #[test]
    fn the_database_has_every_secg_curve() {
        let names = secg_names();
        assert_eq!(names.len(), 33, "{names:?}");
        for n in [
            "secp112r1",
            "secp160k1",
            "secp160r1",
            "secp160r2",
            "secp192r1",
            "sect113r1",
            "sect113r2",
            "sect163k1",
            "sect163r1",
            "sect163r2",
        ] {
            assert!(secg(n).is_some(), "{n}");
        }
        assert!(secg("SECT113R1").is_some());
        assert!(secg("nope").is_none());
    }

    #[test]
    fn binary_entries_match_the_hand_typed_constructors() {
        for (name, ctor) in [
            ("sect113r1", BinaryCurve::sect113r1 as fn() -> BinaryCurve),
            ("sect113r2", BinaryCurve::sect113r2),
            ("sect163r2", BinaryCurve::sect163r2),
        ] {
            let json = secg(name).expect(name);
            let hand = ctor();
            assert_eq!(json.order, hand.order, "{name} order");
            assert_eq!(json.a, hand.a.to_biguint(), "{name} a");
            assert_eq!(json.b, hand.b.to_biguint(), "{name} b");
            let BinaryPoint::Affine { x, y } = &hand.generator else {
                panic!("{name} generator");
            };
            assert_eq!(json.gx, x.to_biguint(), "{name} Gx");
            assert_eq!(json.gy, y.to_biguint(), "{name} Gy");
            let SecgField::Binary { degree, low_terms } = &json.field else {
                panic!("{name} is binary");
            };
            assert_eq!(*degree, hand.irreducible.degree);
            let mut t = hand.irreducible.low_terms.clone();
            t.sort_unstable();
            assert_eq!(low_terms, &t, "{name} polynomial");
            assert_eq!(
                BigUint::from(json.cofactor),
                hand.cofactor,
                "{name} cofactor"
            );
        }
    }

    #[test]
    fn prime_entries_have_the_published_shape() {
        let c = secg("secp160r1").unwrap();
        let SecgField::Prime { p } = &c.field else {
            panic!()
        };
        assert_eq!(p.bits(), 160);
        // a = p − 3 for secp160r1.
        assert_eq!(&c.a + 3u8, *p);
        assert_eq!(c.cofactor, 1);
        assert_eq!(secg("secp192k1").unwrap().a, BigUint::from(0u8));
    }
}
